import { AppModule } from '../../src/app.module.js';
import { io, Socket } from 'socket.io-client';

describe('EventsGateway', () => {
  let app: INestApplication;
  let socket: Socket;

  beforeAll(async () => {
    const moduleRef = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleRef.createNestApplication();
    await app.listen(3000);
  });

  beforeEach(() => {
    return new Promise<void>(resolve => {
      socket = io('http://localhost:3000');
      socket.on('connect', () => {
        resolve();
      });
    });
  });

  describe('findAll', () => {
    it('should receive 3 numbers', () => {
      return new Promise<void>((resolve, reject) => {
        let eventCount = 1;
        socket.emit('events', { test: 'test' });
        socket.on('events', data => {
          try {
            expect(data).toBe(eventCount);
          } catch (err) {
            reject(err);
            return;
          }
          if (++eventCount > 3) {
            resolve();
          }
        });
      });
    });
  });

  describe('identity', () => {
    it('should return the same number has what was sent', () => {
      return new Promise<void>((resolve, reject) => {
        socket.emit('identity', 0, response => {
          try {
            expect(response).toBe(0);
            resolve();
          } catch (err) {
            reject(err);
          }
        });
      });
    });
  });

  afterEach(() => {
    socket.disconnect();
  });

  afterAll(async () => {
    await app.close();
  });
});

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { IoAdapter } from '@nestjs/platform-socket.io';
import { ServerOptions } from 'socket.io';
import { createAdapter } from '@socket.io/redis-adapter';
import { createClient } from 'redis';

export class RedisIoAdapter extends IoAdapter {
  private adapterConstructor: ReturnType<typeof createAdapter>;

  async connectToRedis(): Promise<void> {
    const pubClient = createClient({
      url: `redis://localhost:6379`,
      clientInfoTag: this.getClientInfoTag(),
    });
    const subClient = pubClient.duplicate();

    await Promise.all([pubClient.connect(), subClient.connect()]);

    this.adapterConstructor = createAdapter(pubClient, subClient);
  }

  createIOServer(port: number, options?: ServerOptions): any {
    const server = super.createIOServer(port, options);
    server.adapter(this.adapterConstructor);
    return server;
  }

  private getClientInfoTag(): string {
    try {
      // Try to get NestJS version from package.json
      const entrypoint = fileURLToPath(import.meta.resolve('@nestjs/common'));
      const { version } = JSON.parse(
        readFileSync(join(dirname(entrypoint), 'package.json'), 'utf8'),
      );
      return `nestjs_v${version}`;
    } catch {
      // Fallback if version cannot be determined
      return 'nestjs';
    }
  }
}

