@Injectable()
export class ExceptionInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    return next
      .handle()
      .pipe(
        catchError(err =>
          throwError(
            () =>
              new HttpException(
                'Exception interceptor message',
                HttpStatus.BAD_GATEWAY,
              ),
          ),
        ),
      );
  }
}

