        .get('/cats')
        .expect(200);

      expect(response.body).toHaveLength(2);
      expect(response.body).toEqual(
        expect.arrayContaining([
          expect.objectContaining({ name: 'Whiskers', breed: 'Persian' }),
          expect.objectContaining({ name: 'Luna', breed: 'Siamese' }),
        ]),
      );
    });
  });
