import http from 'http';
import request from 'supertest';
import { AppModule } from '../src/app.module.js';

describe('AppController (e2e)', () => {
  let app: INestApplication;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    await app.init();
  });

  afterAll(async () => {
    await app.close();
  });

  describe('GET /', () => {
    it('should return 200 with HTML content', () => {
      return request(app.getHttpServer())
        .get('/')
        .expect(200)
        .expect('content-type', /text\/html/)
        .expect((res) => {
          expect(res.text).toContain('EventSource');
        });
    });
  });

  describe('GET /sse', () => {
    it('should return text/event-stream and emit event data', () => {
      return new Promise<void>((resolve, reject) => {
        const httpServer = app.getHttpServer();
        if (!httpServer.listening) httpServer.listen(0);
        const { port } = httpServer.address() as AddressInfo;

        let received = '';
        let completed = false;

        const finish = (err?: Error) => {
          if (!completed) {
            completed = true;
            if (err) reject(err);
            else resolve();
          }
        };

        const req = http.get(`http://127.0.0.1:${port}/sse`, (res) => {
          expect(res.statusCode).toBe(200);
          expect(res.headers['content-type']).toContain('text/event-stream');

          res.on('data', (chunk: Buffer) => {
            received += chunk.toString();
            if (received.includes('"hello":"world"')) {
              expect(received).toContain('"hello":"world"');
              req.destroy();
              finish();
            }
          });
        });

        req.on('error', (err: NodeJS.ErrnoException) => {
          if (err.code !== 'ECONNRESET') finish(err);
        });
      });
    }, 5000);
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { firstValueFrom } from 'rxjs';
import { AppController } from './app.controller';

describe('AppController', () => {
  let controller: AppController;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      controllers: [AppController],
    }).compile();

    controller = module.get<AppController>(AppController);
  });

  it('should be defined', () => {
    expect(controller).toBeDefined();
  });

  describe('index', () => {
    it('should respond with text/html and the index.html content', () => {
      const mockResponse = {
        type: vi.fn().mockReturnThis(),
        send: vi.fn(),
      } as any;

      controller.index(mockResponse);

      expect(mockResponse.type).toHaveBeenCalledWith('text/html');
      expect(mockResponse.send).toHaveBeenCalledWith(
        expect.stringContaining('EventSource'),
      );
    });
  });

  describe('sse', () => {
    it('should return an Observable', () => {
      const result = controller.sse();
      expect(result).toBeDefined();
      expect(typeof result.subscribe).toBe('function');
    });

    it('should emit { data: { hello: "world" } } on each interval tick', async () => {
      vi.useFakeTimers();

      const promise = firstValueFrom(controller.sse());
      vi.advanceTimersByTime(1000);
      const event = await promise;

      expect(event).toEqual({ data: { hello: 'world' } });

      vi.useRealTimers();
    });
  });
});

import { Controller, Get, MessageEvent, Res, Sse } from '@nestjs/common';
import { Response } from 'express';
import { readFileSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';
import { interval, Observable } from 'rxjs';
import { map } from 'rxjs/operators';

const __dirname = dirname(fileURLToPath(import.meta.url));

@Controller()
export class AppController {
  @Get()
  index(@Res() response: Response) {
    response
      .type('text/html')
      .send(readFileSync(join(__dirname, 'index.html')).toString());
  }

  @Sse('sse')
  sse(): Observable<MessageEvent> {
    return interval(1000).pipe(
      map((_) => ({ data: { hello: 'world' } }) as MessageEvent),
    );
  }
}

