import { PGlite } from '@electric-sql/pglite';
import { OutboxStorage } from '@nestjs/outbox';
import {
  outboxInboxStoreContract,
  outboxStoreContract,
  type OutboxStoreHarness,
} from '@nestjs/outbox/testing';
import { sql } from 'drizzle-orm';
