    moduleRef = await Test.createTestingModule({ imports: [AppModule] })
      .overrideProvider(getDrizzleToken())
      .useValue(db) // DrizzleOutboxStore injects it too
      .overrideProvider(MailerService)
      .useValue(mailer)
      .overrideProvider(ANALYTICS_SERVICE)
      .useValue(analytics)
      .compile();
    await moduleRef.init();
    orders = moduleRef.get(OrdersService);
    relay = moduleRef.get(OutboxRelay);
  });

  afterAll(async () => {
    await moduleRef.close();
    await client.close();
  });

  it('publishes order events only after the order commits', async () => {
    const order = await orders.placeOrder({
      userId: 'user-42',
      items: [{ productId: 'salmon-kibble-2kg', quantity: 1 }],
    });
    expect(mailer.sendOrderConfirmation).not.toHaveBeenCalled();

    await relay.runOnce(); // claim and publish one batch

    expect(mailer.sendOrderConfirmation).toHaveBeenCalledWith(order);
    expect(analytics.emit).toHaveBeenCalledWith(
      'analytics.order.placed',
      expect.objectContaining({ key: order.id, payload: order }),
    );
    expect(await relay.stats()).toMatchObject({ pending: 0, deadLetters: 0 });
  });

  it('publishes nothing when the transaction rolls back', async () => {
    const outbox = moduleRef.get(Outbox);
    const add = outbox.add.bind(outbox);
    vi.spyOn(outbox, 'add').mockImplementationOnce(async (tx, messages) => {
      await add(tx, messages); // the messages are written...
      throw new Error('Connection terminated unexpectedly'); // ...then the transaction fails
    });

    await expect(
      orders.placeOrder({
        userId: 'user-42',
        items: [{ productId: 'salmon-kibble-2kg', quantity: 1 }],
      }),
    ).rejects.toThrow('Connection terminated unexpectedly');

    expect(await relay.stats()).toMatchObject({ pending: 0 });
    expect(await relay.runOnce()).toMatchObject({ claimed: 0 });
  });
});

import type { LoggerService } from '@nestjs/common';
import { createServer } from 'node:net';

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/** Waits until `check` passes. */
export async function until(
  check: () => boolean | Promise<boolean>,
  timeout = 5_000,
) {
  const start = Date.now();
  while (!(await check())) {
    if (Date.now() - start > timeout) throw new Error('Timed out waiting');
    await sleep(10);
  }
}

/** Keeps what the application logs, as `[Context] message` lines. */
export function capturingLogger() {
  const lines: string[] = [];
  const write = (message: unknown, ...rest: unknown[]) => {
    const context = rest.at(-1);
    lines.push(
      typeof context === 'string' ? `[${context}] ${message}` : String(message),
    );
  };
  const logger: LoggerService = { log: write, warn: write, error: write };
  return {
    logger,
    lines,
    matching: (line: string) => lines.filter(logged => logged === line),
  };
}

/** A port nothing listens on, on the loopback interface. */
export function freePort(): Promise<number> {
  return new Promise((resolve, reject) => {
    const server = createServer();
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      const { port } = server.address() as { port: number };
      server.close(() => resolve(port));
    });
  });
}

/**
 * The PostgreSQL server the store suites run on: the one in `SQL_TEST_PG_URL`, e.g. the
 * container of docker-compose.yml (`postgres://postgres:postgres@localhost:5432/postgres`).
 * Resolves to `null`, with the reason, without one, so a suite can skip with a clear message
 * instead of failing.
 */
import pg from 'pg';

export interface TestPostgres {
  /** Creates a database (dropping a previous one with the same name) and returns its URL. */
  createDatabase(name: string): Promise<string>;
  /** Drops the databases this process created. */
  stop(): Promise<void>;
}

export type TestPostgresResult =
  | { postgres: TestPostgres; reason?: undefined }
  | { postgres: null; reason: string };

export async function startPostgres(): Promise<TestPostgresResult> {
  const connectionString = process.env.SQL_TEST_PG_URL;
  if (!connectionString)
    return { postgres: null, reason: 'SQL_TEST_PG_URL is not set' };
  try {
    await run(connectionString, 'SELECT 1');
  } catch (error) {
    return {
      postgres: null,
      reason: `no server at SQL_TEST_PG_URL: ${(error as Error).message}`,
    };
  }

  // Several test files share the server, so every database gets a suffix of its own, and
  // nothing is dropped except the databases created here.
  const suffix = `_${process.pid}_${Math.random().toString(36).slice(2, 8)}`;
  const created: string[] = [];
  return {
    postgres: {
      async createDatabase(name) {
        const database = name + suffix;
        await run(
          connectionString,
          `DROP DATABASE IF EXISTS "${database}" WITH (FORCE)`,
        );
        await run(connectionString, `CREATE DATABASE "${database}"`);
        created.push(database);
        const url = new URL(connectionString);
        url.pathname = `/${database}`;
        return url.toString();
      },
      async stop() {
        for (const database of created.splice(0)) {
          await run(
            connectionString,
            `DROP DATABASE IF EXISTS "${database}" WITH (FORCE)`,
          );
        }
      },
    },
  };
}

async function run(connectionString: string, statement: string): Promise<void> {
  const client = new pg.Client({ connectionString });
  await client.connect();
  try {
    await client.query(statement);
  } finally {
    await client.end();
  }
}

import { Module } from '@nestjs/common';
